'use strict';
const STORAGE_KEY='leonida-playbook-progress-v1';
const stageInfo=[
 {name:'',hours:0,goal:''},
 {name:'Chapter 1 — and the one missable',hours:6,goal:'Secure the balcony meditation lesson and preserve a clean chapter save before the world opens.'},
 {name:'Chapters 2–4 — the story spine',hours:45,goal:'Advance the story steadily, saving at every chapter start and leaving cheats disabled.'},
 {name:'Strangers & Freaks — start every chain early',hours:25,goal:'Pick up each stranger strand as soon as it appears and finish its window promptly.'},
 {name:'Activities & mastery',hours:35,goal:'Rotate through activity types, then focus on medals, races, stunts and challenges.'},
 {name:'Crime, partners & free-roam feats',hours:25,goal:'Prepare crime attempts, partner requirements and combat feats during open-world cleanup.'},
 {name:'Collectibles, cash & the whole map',hours:55,goal:'Sweep the map by region and monitor the long counters for cash, vehicles and discoveries.'},
 {name:'100% and the platinum',hours:9,goal:'Compare remaining work with the in-game checklist and claim the final completion trophies.'}
];
const demo={earned:{2:true,3:true,4:true,8:true,9:true,16:true,20:true,21:true,33:true,36:true,44:true,46:true,51:true},counters:{17:31,15:87,31:12}};
let data;let state={earned:{},counters:{},chapter:'1',spoiler:false,tab:'tracker',kind:'all',grade:'all',query:'',earnedOnly:false,riskOnly:false,selectedId:28};
const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function readSavedProgress(){try{const x=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');return {earned:x.earned&&typeof x.earned==='object'?x.earned:{},counters:x.counters&&typeof x.counters==='object'?x.counters:{},chapter:['1','2','3','4','post'].includes(x.chapter)?x.chapter:'1',spoiler:typeof x.spoiler==='boolean'?x.spoiler:false};}catch{return {earned:{},counters:{},chapter:'1',spoiler:false};}}
function saveProgress(){localStorage.setItem(STORAGE_KEY,JSON.stringify({earned:state.earned,counters:state.counters,chapter:state.chapter,spoiler:state.spoiler}));}
function trophyById(id){return data.trophies.find(t=>t.id===Number(id));}
function earnedCount(){return data.trophies.filter(t=>state.earned[t.id]).length;}
function gradeCounts(){return Object.fromEntries(['platinum','gold','silver','bronze'].map(g=>[g,{earned:data.trophies.filter(t=>t.grade===g&&state.earned[t.id]).length,total:data.trophies.filter(t=>t.grade===g).length}]));}
function stageProgress(stage){const list=data.trophies.filter(t=>t.stage===stage);return {earned:list.filter(t=>state.earned[t.id]).length,total:list.length};}
function hoursToGo(){return data.trophies.filter(t=>!state.earned[t.id]).reduce((sum,t)=>sum+(stageInfo[t.stage].hours/(data.trophies.filter(x=>x.stage===t.stage).length||1)),0);}
function chapterWarnings(){const copy={
 '1':'<strong>Positive Mental Attitude:</strong> the morning after <em>Down to Earth</em>, follow Lucia to Jason’s balcony and accept her lesson. Do it before Chapter 1 ends, and keep a Chapter 1 save. It is a safe +1 although it is not a marked spot.',
 '2':'Start each stranger chain as soon as it appears; story progress can close its window (TechWiser). Save at every chapter start; keep cheats off on the trophy save.',
 '3':'Start each stranger chain as soon as it appears; story progress can close its window (TechWiser). Save at every chapter start; keep cheats off on the trophy save.',
 '4':'Start each stranger chain as soon as it appears; story progress can close its window (TechWiser). Save at every chapter start; keep cheats off on the trophy save.',
 'post':'Nothing story-locked remains. Clean up counters first, collectibles second, then push for 100%.'};return copy[state.chapter];}
function nextUpQueue(){const earned=data.trophies.filter(t=>!state.earned[t.id]);const urgent=earned.filter(t=>t.stage===Number(state.chapter)&&t.missable);const chosen=[...urgent,...earned.filter(t=>!urgent.includes(t))];return chosen.sort((a,b)=>a.stage-b.stage||a.id-b.id).slice(0,3);}
function loadTrophies(){return fetch('data/trophies.json').then(r=>{if(!r.ok)throw new Error('Could not load the local trophy list');return r.json();}).then(doc=>{data=doc;});}
function renderHeader(){const n=earnedCount(),grades=gradeCounts();$('progress-card').innerHTML=`<div class="progress-top"><strong class="big-count">${n} / 55</strong><span class="progress-percent">${Math.round(n/55*100)}% to the platinum</span></div><div class="bar"><i style="width:${n/55*100}%"></i></div><div class="grade-counts">${Object.entries(grades).map(([g,v])=>`<span>${g} ${v.earned}/${v.total}</span>`).join(' · ')}</div><div class="stage-mini">${stageInfo.slice(1).map((_,i)=>{const p=stageProgress(i+1);return `<span>S${i+1} ${p.earned}/${p.total}</span>`}).join('')}</div><div class="hours">About ${Math.ceil(hoursToGo())} hours to go · estimate based on stage budgets</div>`;}
function renderToolbar(){const kinds=['all','story','side story','collectibles','activities','robbery','exploration & misc','completion'];$('toolbar-controls').innerHTML=`<div class="tool-row"><input id="search" type="search" placeholder="Search trophies, guides and sources…" value="${esc(state.query)}" aria-label="Search trophies"><div class="chips">${kinds.map(k=>`<button class="chip ${state.kind===k?'active':''}" data-kind="${esc(k)}">${k==='all'?'All 55':k==='completion'?'100% completion':k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</div><select id="grade-filter" aria-label="Filter by grade"><option value="all">All grades</option>${['platinum','gold','silver','bronze'].map(x=>`<option value="${x}" ${state.grade===x?'selected':''}>${x[0].toUpperCase()+x.slice(1)}</option>`).join('')}</select></div><div class="tool-row"><label class="toggle"><input id="spoiler" type="checkbox" ${state.spoiler?'checked':''}>Hide story spoilers</label><label class="toggle"><input id="earned-only" type="checkbox" ${state.earnedOnly?'checked':''}>Earned only</label><label class="toggle"><input id="risk-only" type="checkbox" ${state.riskOnly?'checked':''}>Missable &amp; at-risk only</label><button class="small-btn" id="export">Export progress</button><label class="small-btn">Import progress<input id="import" type="file" accept="application/json" hidden></label><button class="small-btn danger-btn" id="reset">Reset</button></div>`;
 $('search').oninput=e=>{state.query=e.target.value;renderAll();$('search').focus();$('search').setSelectionRange(state.query.length,state.query.length)};
 document.querySelectorAll('[data-kind]').forEach(b=>b.onclick=()=>{state.kind=b.dataset.kind;renderAll()});$('grade-filter').onchange=e=>{state.grade=e.target.value;renderAll()};$('spoiler').onchange=e=>{state.spoiler=e.target.checked;saveProgress();renderAll()};$('earned-only').onchange=e=>{state.earnedOnly=e.target.checked;renderAll()};$('risk-only').onchange=e=>{state.riskOnly=e.target.checked;renderAll()};$('chapter').value=state.chapter;$('chapter').onchange=e=>{state.chapter=e.target.value;saveProgress();renderAll()};$('export').onclick=exportProgress;$('import').onchange=importProgress;$('reset').onclick=resetProgress;
}
function visibleTrophies(){const q=state.query.toLowerCase();return data.trophies.filter(t=>(state.kind==='all'||t.kind===state.kind)&&(state.grade==='all'||t.grade===state.grade)&&(!state.earnedOnly||state.earned[t.id])&&(!state.riskOnly||t.missable)&&(!q||[t.name,t.description,t.guide,t.kind,...t.sources].join(' ').toLowerCase().includes(q)));}
function counterStepper(t){if(!t.count)return '';const n=Math.min(t.count,Number(state.counters[t.id]||0));return `<div class="counter" data-counter="${t.id}"><button type="button" data-step="-1" aria-label="Decrease ${esc(t.name)} counter">−</button><span class="counter-text">${n} / ${t.count} ${esc(t.countLabel)}</span><button type="button" data-step="1" aria-label="Increase ${esc(t.name)} counter">+</button><span class="bar"><i style="width:${n/t.count*100}%"></i></span></div>`;}
function rowTitle(t){return state.spoiler&&t.kind==='story'&&!state.earned[t.id]?'Hidden trophy':t.name;}
function renderChecklist(){const list=visibleTrophies();$('showing-line').textContent=`Showing ${list.length} of 55 trophies · progress saves automatically in this browser`;
 const next=nextUpQueue();$('view-tracker').innerHTML=`<div class="next-strip">${next.map((t,i)=>`<div class="next-card ${t.missable?'alert':''}" data-select="${t.id}"><small>${t.missable?'⚠ ':''}NEXT ${i+1} · STAGE ${t.stage} · ${esc(t.kind)}</small><strong>${esc(rowTitle(t))}</strong></div>`).join('')}</div><div class="tracker-grid"><div class="checklist"><div class="list-head"><h2>Trophy checklist</h2><span class="muted">${list.length} visible</span></div>${list.map(t=>{const shield=state.spoiler&&t.kind==='story'&&!state.earned[t.id];return `<article class="trophy-row ${state.earned[t.id]?'earned':''} ${state.selectedId===t.id?'selected':''}" data-row="${t.id}"><input type="checkbox" data-earned="${t.id}" aria-label="Mark ${esc(rowTitle(t))} earned" ${state.earned[t.id]?'checked':''}><div class="trophy-main"><div class="row-title">${esc(rowTitle(t))}</div><div class="row-desc">${shield?'Story trophy — shielded by your spoiler setting. Earn it in game, or turn the shield off to peek.':esc(t.description)}</div><div class="badges"><span class="badge grade">${t.grade}</span>${t.hidden?'<span class="badge">Hidden on PSN</span>':''}${t.missable==='missable'?'<span class="badge missable">Missable</span>':''}${t.missable==='at-risk'?'<span class="badge risk">At risk</span>':''}<span class="badge">${esc(t.kind)}</span><span class="badge stage">Stage ${t.stage}</span></div>${counterStepper(t)}</div></article>`}).join('')||'<p class="muted" style="padding:14px">No trophies match these filters.</p>'}</div><aside id="guide-panel" class="guide-panel"></aside></div>`;
 document.querySelectorAll('[data-row]').forEach(el=>el.onclick=e=>{if(e.target.closest('input[type=checkbox],.counter'))return;state.selectedId=Number(el.dataset.row);renderAll()});document.querySelectorAll('[data-earned]').forEach(box=>box.onchange=()=>{const id=Number(box.dataset.earned);state.earned[id]=box.checked;if(!box.checked)delete state.earned[id];saveProgress();renderAll()});document.querySelectorAll('[data-select]').forEach(el=>el.onclick=()=>{state.selectedId=Number(el.dataset.select);renderAll()});document.querySelectorAll('[data-step]').forEach(b=>b.onclick=e=>{e.stopPropagation();changeCounter(Number(b.closest('[data-counter]').dataset.counter),Number(b.dataset.step))});renderGuidePanel();
}
function renderGuidePanel(){const t=trophyById(state.selectedId)||data.trophies[0];const callout=t.missable?`<div class="callout ${t.missable==='at-risk'?'risk':''}"><strong>${t.missable==='missable'?'MISSABLE':'AT RISK'}</strong><br>${esc(t.missableNote)}</div>`:'';const counterTop=t.id===17?counterStepper(t):'';const links=t.sources.map(name=>{const s=data.sources.find(x=>x.name===name);return `<a href="${esc(s?.url||'#')}" target="_blank" rel="noreferrer">${esc(name)}</a>`}).join(' · ');$('guide-panel').innerHTML=`<div class="panel-head"><span class="eyebrow">SELECTED GUIDE</span><span class="badge">${t.grade} · ${esc(t.kind)} · stage ${t.stage}</span></div><div class="source-row"><b>SOURCES</b> ${links}</div><h2 class="guide-title">${esc(rowTitle(t))}</h2><div class="official"><strong>Official description:</strong> “${esc(t.description)}”</div>${counterTop}${callout}<h3>GUIDE — IN OUR OWN WORDS</h3><p class="guide-copy">${esc(t.guide)}</p><h3>STEPS</h3><ol>${t.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>${counterStepper(t)}`;document.querySelectorAll('#guide-panel [data-step]').forEach(b=>b.onclick=()=>changeCounter(Number(b.closest('[data-counter]').dataset.counter),Number(b.dataset.step)));}
function changeCounter(id,delta){const t=trophyById(id);if(!t?.count)return;state.counters[id]=Math.max(0,Math.min(t.count,Number(state.counters[id]||0)+delta));if(state.counters[id]>=t.count)state.earned[id]=true;saveProgress();renderAll();}
function renderRoadmap(){const intro=`PowerPyx estimates about 200 hours at 4/10 difficulty. One playthrough is enough; there is no mission replay or New Game+, so keep a manual save at the start of every chapter and an untouched save before the final mission. Cheats disable trophies and saving on the trophy run. <a href="${esc(data.sources[1].url)}" target="_blank" rel="noreferrer">PowerPyx roadmap</a>.`;$('view-roadmap').innerHTML=`<p class="guide-copy">${intro}</p><div class="stage-grid">${stageInfo.slice(1).map((s,i)=>{const n=i+1,p=stageProgress(n),items=data.trophies.filter(t=>t.stage===n);return `<article class="stage-card"><span class="stage-number">ROADMAP STAGE ${n}</span><h2>${esc(s.name)}</h2><div class="stage-meta"><span>${s.hours}h budget</span><span>${p.earned}/${p.total} trophies</span></div><div class="bar"><i style="width:${p.total?p.earned/p.total*100:0}%"></i></div><p>${esc(s.goal)}</p>${n===1?'<p class="point-note">Point of no return: the balcony meditation lesson disappears when Chapter 1 ends.</p>':''}${n===3?'<p class="point-note">Story windows may apply: begin each stranger chain as soon as it appears.</p>':''}<div class="trophy-chips">${items.map(t=>`<button class="trophy-chip ${state.earned[t.id]?'earned':''}" data-jump="${t.id}">${state.earned[t.id]?'✓ ':''}${esc(t.name)}</button>`).join('')}</div></article>`}).join('')}</div>`;document.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{state.selectedId=Number(b.dataset.jump);state.tab='tracker';renderAll()});}
function renderMissables(){const t=data.trophies.find(x=>x.missable==='missable'),risks=data.trophies.filter(x=>x.missable==='at-risk');$('view-missables').innerHTML=`<article class="missable-card"><span class="badge missable">ONE TRUE MISSABLE · CHAPTER 1</span><p class="source-row">${t.sources.map(n=>{const s=data.sources.find(x=>x.name===n);return `<a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(n)}</a>`}).join(' · ')}</p><h2>${esc(t.name)}</h2><p><strong>Official description:</strong> ${esc(t.description)}</p><div class="callout"><strong>Do this before Chapter 1 ends.</strong><br>${esc(t.missableNote)} The morning after <em>Down to Earth</em>, Lucia meditates on the balcony at Jason’s house. Follow her, choose Accept, and let her teach you. That lesson adds +1 but is not marked as a spot; whether it is required remains unconfirmed, so doing it is the safe play. The 100% checklist needs 15 of 18, while this trophy requires all 18. Both Jason and Lucia meditating at one spot count twice.</div></article><h2 class="section-title">AT-RISK STRANGER CHAINS</h2><table class="risk-table"><thead><tr><th>Trophy</th><th>Character / chain</th><th>Window</th><th>Advice</th></tr></thead><tbody>${risks.map(x=>`<tr><td><strong>${esc(x.name)}</strong><br>${esc(x.description)}</td><td>${x.id===29?'Bret':x.id===22?'Andy':x.id===23?'Kenton':x.id===24?'Billy':x.id===26?'Randy':'Tyrone'}</td><td>Chain window tied to story progress (TechWiser).</td><td>Start as soon as it appears; finish before advancing deep into later chapters.</td></tr>`).join('')}</tbody></table><div class="reassurance"><strong>Everything else can wait for cleanup.</strong> Story trophies pop by playing the named missions. Free-roam, activity, collectible and crime trophies remain available after the story because the world stays open; the PowerPyx roadmap says one playthrough is enough.</div>`;}
function renderSources(){ $('view-sources').innerHTML=`<div class="honesty-grid"><article class="honesty-card"><h2>Sources</h2><table class="sources-table"><tbody>${data.sources.map(s=>`<tr><td><a href="${esc(s.url)}" target="_blank" rel="noreferrer">${esc(s.name)}</a></td><td>${esc(s.usedFor)}</td></tr>`).join('')}</tbody></table></article><article class="honesty-card"><h2>Honesty notes</h2><ul><li>Guides are written for this entry in our own words; sources are listed beside each trophy.</li><li>Official names, descriptions and grades are PlayStation’s, as Exophase and PSNProfiles listed them on 18 Nov 2026; both lists agree.</li><li>When a description is a joke, we say so and label its plain reading.</li><li>No Rockstar logo or official artwork appears here.</li><li>This app works offline and fetches nothing; source pages open only if you follow a link.</li><li>Progress lives only in this browser’s localStorage. Export and Import move it as a JSON file.</li></ul><button id="demo" class="demo-btn">Load demo progress</button><p class="muted">Demo shows the tracker with a few earned trophies and live counters. Reset clears it.</p></article></div>`;$('demo').onclick=loadDemoProgress;}
function renderTabs(){document.body.dataset.tab=state.tab;document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===state.tab);b.onclick=()=>{state.tab=b.dataset.tab;renderAll()}});document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${state.tab}`));}
function renderAll(){if(!data)return;renderHeader();renderToolbar();$('chapter-warning').innerHTML=chapterWarnings();renderChecklist();renderRoadmap();renderMissables();renderSources();renderTabs();}
function applyUrlState(){const p=new URLSearchParams(location.search);if(p.has('view')&&['tracker','roadmap','missables','sources'].includes(p.get('view')))state.tab=p.get('view');if(p.has('spoiler'))state.spoiler=p.get('spoiler')==='on';if(p.has('chapter')&&['1','2','3','4','post'].includes(p.get('chapter')))state.chapter=p.get('chapter');if(p.has('select')&&trophyById(p.get('select')))state.selectedId=Number(p.get('select'));if(p.has('kind')&&['all','story','side story','collectibles','activities','robbery','exploration & misc','completion'].includes(p.get('kind')))state.kind=p.get('kind');if(p.has('grade')&&['all','platinum','gold','silver','bronze'].includes(p.get('grade')))state.grade=p.get('grade');if(p.get('seed')==='demo'){state.earned={...demo.earned};state.counters={...demo.counters};}}
function exportProgress(){const payload={version:1,earned:state.earned,counters:state.counters,chapter:state.chapter,spoiler:state.spoiler};const url=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='leonida-playbook-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function importProgress(event){const file=event.target.files?.[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(!obj||typeof obj!=='object'||!obj.earned||typeof obj.earned!=='object'||!obj.counters||typeof obj.counters!=='object')throw new Error('Invalid progress file');const ids=new Set(data.trophies.map(t=>t.id));state.earned={};for(const [id,value] of Object.entries(obj.earned))if(ids.has(Number(id))&&value===true)state.earned[id]=true;state.counters={};for(const [id,value] of Object.entries(obj.counters)){const t=trophyById(id);if(t?.count&&Number.isFinite(Number(value)))state.counters[id]=Math.max(0,Math.min(t.count,Math.floor(Number(value))));}if(['1','2','3','4','post'].includes(obj.chapter))state.chapter=obj.chapter;if(typeof obj.spoiler==='boolean')state.spoiler=obj.spoiler;saveProgress();renderAll();}catch{alert('This file is not a valid Leonida Playbook progress export.');}event.target.value='';}
function resetProgress(){if(!confirm('Clear all saved Leonida Playbook progress in this browser?'))return;localStorage.removeItem(STORAGE_KEY);state.earned={};state.counters={};state.chapter='1';state.spoiler=false;renderAll();}
function loadDemoProgress(){state.earned={...demo.earned};state.counters={...demo.counters};saveProgress();renderAll();}
async function start(){await loadTrophies();Object.assign(state,readSavedProgress());applyUrlState();renderAll();}
start().catch(error=>{document.getElementById('main-content').innerHTML=`<section class="missable-card"><h2>Could not load the local guide</h2><p>${esc(error.message)}. Open this folder through the included static server so the local data file can load.</p></section>`;});
